app.use((req, res, next) => {
  res.status(404).json({ error: 'Resource not found' });
});

// 6. Centralized Global Error Handler
app.use((err, req, res, next) => {
  // Log the error internally (use a production logger like Winston or Bunyan in real apps)
  console.error(`[Error] ${err.message}`, {
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Respond with a generic message to prevent information leakage
  const statusCode = err.status || 500;
  res.status(statusCode).json({
    error: {
      message: statusCode === 500 ? 'Internal Server Error' : err.message
    }
  });
});

// 7. Dynamic Port Binding
