const validateUsersQuery = (req, res, next) => {
  const { limit, page } = req.query;

  if (limit !== undefined) {
    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
      const err = new Error('Invalid "limit" parameter. It must be a positive integer between 1 and 100.');
      err.status = 400;
      return next(err);
    }
    req.validatedQuery = { ...req.validatedQuery, limit: parsedLimit };
  }

  if (page !== undefined) {
    const parsedPage = parseInt(page, 10);
    if (isNaN(parsedPage) || parsedPage <= 0) {
      const err = new Error('Invalid "page" parameter. It must be a positive integer.');
      err.status = 400;
      return next(err);
    }
    req.validatedQuery = { ...req.validatedQuery, page: parsedPage };
  }

  next();
};

// Users endpoint with input validation
app.get('/users', validateUsersQuery, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination if query parameters are validated and present
  if (req.validatedQuery) {
    const { limit, page } = req.validatedQuery;
    if (limit || page) {
      const p = page || 1;
      const l = limit || 10;
      const startIndex = (p - 1) * l;
      const endIndex = p * l;
      return res.json(users.slice(startIndex, endIndex));
    }
  }

  res.json(users);
});

// 404 Handler for undefined routes
app.use((req, res, next) => {
  const err = new Error(`Route ${req.originalUrl} not found`);
  err.status = 404;
  next(err);
});

