const express = require('express');
const app = express();

// Parse JSON bodies
app.use(express.json());

// Helper function for input validation
const validatePagination = (req, res, next) => {
  const { limit, page } = req.query;

  if (limit !== undefined) {
    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'The "limit" query parameter must be a positive integer between 1 and 100.'
      });
    }
    req.validatedLimit = parsedLimit;
  } else {
    req.validatedLimit = 10; // Default limit
  }

  if (page !== undefined) {
    const parsedPage = parseInt(page, 10);
    if (isNaN(parsedPage) || parsedPage <= 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'The "page" query parameter must be a positive integer.'
      });
    }
    req.validatedPage = parsedPage;
  } else {
    req.validatedPage = 1; // Default page
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation and pagination
app.get('/users', validatePagination, (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination based on validated inputs
    const limit = req.validatedLimit;
    const page = req.validatedPage;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (error) {
    next(error); // Pass errors to the centralized error handler
  }
});

// 404 Handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Centralized Error Handling Middleware
// Focuses on security by not leaking stack traces in production
app.use((err, req, res, next) => {
  console.error(`[Error] ${err.stack || err.message || err}`);

  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isProduction ? 'An unexpected error occurred.' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

