  const { limit, page } = req.query;

  if (limit !== undefined) {
    const limitNum = Number(limit);
    if (!Number.isInteger(limitNum) || limitNum <= 0 || limitNum > 100) {
      const err = new Error('Invalid query parameter: "limit" must be a positive integer between 1 and 100.');
      err.status = 400;
      return next(err);
    }
    req.query.limit = limitNum; // Store sanitized value
  }

  if (page !== undefined) {
    const pageNum = Number(page);
    if (!Number.isInteger(pageNum) || pageNum <= 0) {
      const err = new Error('Invalid query parameter: "page" must be a positive integer.');
      err.status = 400;
      return next(err);
    }
    req.query.page = pageNum; // Store sanitized value
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation and pagination support
app.get('/users', validateUsersQuery, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const limit = req.query.limit || 10;
  const page = req.query.page || 1;
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;

  const paginatedUsers = users.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
    }
  });
});

// Catch-all middleware for undefined routes (404 Not Found)
app.use((req, res, next) => {
  const err = new Error(`Route ${req.originalUrl} not found`);
  err.status = 404;
  next(err);
});

// Centralized error handling middleware
const isProduction = process.env.NODE_ENV === 'production';
app.use((err, req, res, next) => {
  const status = err.status || 500;

  // Log the error internally (in production, use a proper logging library like Winston or Bunyan)
  console.error(`[Error] Status: ${status} - Message: ${err.message}`);
  if (status === 500 && err.stack) {
    console.error(err.stack);
  }

  // Return a clean, standardized JSON response
  res.status(status).json({
    error: {
      status,
      message: isProduction && status === 500 ? 'Internal Server Error' : err.message,
    }
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

