// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

// Security: Disable X-Powered-By header to prevent technology fingerprinting
app.disable('x-powered-by');

// Middleware to parse JSON bodies (if POST/PUT requests are added later)
app.use(express.json());

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Get all users
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Get user by ID with input validation and error handling
app.get('/users/:id', (req, res, next) => {
  const { id } = req.params;

  // Input Validation: Ensure ID is a positive integer
  const userId = Number(id);
  if (!Number.isInteger(userId) || userId <= 0) {
    const error = new Error('Invalid User ID. Must be a positive integer.');
    error.status = 400;
    return next(error);
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);
  if (!user) {
    const error = new Error('User not found');
    error.status = 404;
    return next(error);
  }

  res.json(user);
});

// 404 Handler for undefined routes
app.use((req, res, next) => {
  const error = new Error(`Route ${req.originalUrl} not found`);
  error.status = 404;
  next(error);
});

// Centralized Error Handling Middleware
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  // Log the error details internally
  console.error(`[Error] ${status} - ${err.message}`, !isProduction ? err.stack : '');

  // Respond to client without leaking sensitive stack traces in production
  res.status(status).json({
    error: {
      status,
      message: status === 500 && isProduction ? 'Internal Server Error' : err.message,
    }
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

