  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation for query parameters
app.get('/users', (req, res, next) => {
  try {
    // Input Validation & Sanitization
    let limit = parseInt(req.query.limit, 10);
    let page = parseInt(req.query.page, 10);

    if (req.query.limit !== undefined && (isNaN(limit) || limit <= 0 || limit > 100)) {
      const err = new Error('Invalid value for "limit". It must be a positive integer up to 100.');
      err.status = 400;
      throw err;
    }

    if (req.query.page !== undefined && (isNaN(page) || page <= 0)) {
      const err = new Error('Invalid value for "page". It must be a positive integer.');
      err.status = 400;
      throw err;
    }

    // Default values if not provided
    limit = limit || 10;
    page = page || 1;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Paginate results
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      page,
      limit,
      total: users.length
    });
  } catch (error) {
    next(error);
  }
});

// Handle 404 - Route Not Found
app.use((req, res, next) => {
  const err = new Error('Not Found');
  err.status = 404;
  next(err);
});

// Centralized Error Handling Middleware
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  // Log error internally (avoid console.log in production, use a logger like winston/bunyan)
  console.error(`[Error] ${status} - ${message}`);
  if (status === 500) {
    console.error(err.stack);
  }

  // Send secure, non-leaking error response to client
  res.status(status).json({
    error: {
      status,
      message: status === 500 ? 'An unexpected error occurred on the server.' : message
    }
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

